namespace Yingge.Cloud.Accounts.Storage;

// Report bodies live outside the content root, under a directory the web
// server never serves. Keys are generated by the service, never by a client.
internal sealed class ReportFileStore
{
    readonly string rootWithSeparator;

    public ReportFileStore(StorageOptions options)
    {
        Root = Path.GetFullPath(options.RootPath);
        rootWithSeparator = Root.TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar;
        Directory.CreateDirectory(Root);
    }

    public string Root { get; }

    public string CreateKey(Guid id, DateTimeOffset receivedAt) =>
        $"reports/{receivedAt:yyyy}/{receivedAt:MM}/{id:N}.json";

    public async Task<int> WriteAsync(string storageKey, byte[] content, CancellationToken ct)
    {
        var path = Resolve(storageKey);
        var directory = Path.GetDirectoryName(path)!;
        Directory.CreateDirectory(directory);

        await using (var stream = new FileStream(path, FileMode.CreateNew, FileAccess.Write,
                         FileShare.None, 64 * 1024, FileOptions.Asynchronous))
        {
            await stream.WriteAsync(content, ct);
            await stream.FlushAsync(ct);
        }

        HardenPermissions(path);
        return content.Length;
    }

    public Task DeleteAsync(string storageKey, CancellationToken ct)
    {
        var path = Resolve(storageKey);
        if (File.Exists(path)) File.Delete(path);
        return Task.CompletedTask;
    }

    public bool Exists(string storageKey) => File.Exists(Resolve(storageKey));

    public string Resolve(string storageKey)
    {
        if (string.IsNullOrWhiteSpace(storageKey) || Path.IsPathRooted(storageKey) ||
            storageKey.Contains("..", StringComparison.Ordinal))
            throw new InvalidOperationException("非法的日志存放键。");

        var path = Path.GetFullPath(Path.Combine(Root, storageKey.Replace('/', Path.DirectorySeparatorChar)));
        var comparison = OperatingSystem.IsWindows()
            ? StringComparison.OrdinalIgnoreCase
            : StringComparison.Ordinal;
        if (!path.StartsWith(rootWithSeparator, comparison))
            throw new InvalidOperationException("日志路径超出允许的存放目录。");
        return path;
    }

    static void HardenPermissions(string path)
    {
        if (OperatingSystem.IsWindows()) return;
        try
        {
            File.SetUnixFileMode(path, UnixFileMode.UserRead | UnixFileMode.UserWrite);
        }
        catch (IOException)
        {
            // Best effort; the directory mode set by the operator is the real
            // boundary and the deployment guide requires 0700.
        }
    }
}
